<?php require 'config.php';require_login();$s=db()->prepare('SELECT * FROM reports WHERE user_id=? ORDER BY report_date DESC');$s->execute([current_user()['id']]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);$title='Reports | MediBook';require 'partials/header.php';?><section class="page-title"><span class="eyebrow">Confidential area</span><h1>Medical reports</h1><p>Only demo metadata is shown. Real medical files are intentionally not included.</p></section><section class="section"><div class="privacy">🔒 Reports must only be shared with the verified patient or an explicitly authorized recipient through approved channels.</div><?php foreach($rows as $r):?><article class="report"><div class="fileicon">PDF</div><div><h3><?=e($r['title'])?></h3><p><?=e($r['doctor_name'])?> • <?=e($r['report_date'])?></p></div><button class="btn small ghost" onclick="alert('Demo report: no real medical document is stored.')">Preview demo</button></article><?php endforeach;?></section><?php require 'partials/footer.php';?>